+    if (posture.target_node_id && !nodeIds.has(posture.target_node_id)) {
+      diagnostics.push({
+        code: 'posture_target_missing',
+        posture_id: posture.posture_id ?? null,
+        target_node_id: posture.target_node_id,
+        severity: 'critical',
+      });
+    }
+    for (const [field, value] of Object.entries(asObject(posture.values))) {
+      const allowedValues = allowed.get(field);
+      if (!allowedValues) {
+        diagnostics.push({
+          code: 'unknown_posture_field',
+          posture_id: posture.posture_id ?? null,
+          field,
+          value,
+          severity: 'critical',
+        });
+        continue;
+      }
+      if (!allowedValues.has(JSON.stringify(value))) {
+        diagnostics.push({
+          code: 'invalid_posture_enum',
+          posture_id: posture.posture_id ?? null,
+          field,
+          value,
+          severity: 'critical',
+        });
+      }
+    }
+  }
+
+  return diagnostics.sort((left, right) => compareByteOrder(left.posture_id, right.posture_id)
+    || compareByteOrder(left.field, right.field)
+    || compareByteOrder(left.code, right.code));
+}
+
+function check(id, condition, extra = {}) {
+  return {
+    id,
+    status: condition ? 'pass' : 'fail',
+    ...extra,
+  };
+}
+
+function countMismatches(graph) {
+  const summary = asObject(graph?.compile_summary);
+  const expected = {
+    node_count: asArray(graph?.nodes).length,
+    edge_count: asArray(graph?.edges).length,
+    posture_count: asArray(graph?.postures).length,
+    source_count: asArray(graph?.sources).length,
+  };
+  return Object.entries(expected)
+    .filter(([field, value]) => summary[field] !== value)
+    .map(([field, value]) => ({ field, expected: value, observed: summary[field] ?? null }));
+}
