+export function validateKgV1RuntimeSpine(graph, options = {}) {
+  const root = options.root ?? repoRootFromScript();
+  const inputDiagnostics = [];
+  const contract = loadContractForValidation(graph, root, inputDiagnostics);
+  const staleDiagnostics = staleReferenceDiagnostics(graph, root);
+  const postureIssues = postureDiagnostics(graph, contract);
+  const nodes = asArray(graph?.nodes);
+  const edges = asArray(graph?.edges);
+  const postures = asArray(graph?.postures);
+  const sources = asArray(graph?.sources);
+
+  const duplicateNodeIds = duplicateValues(nodes.map((node) => node.node_id));
+  const duplicateEdgeIds = duplicateValues(edges.map((edge) => edge.edge_id));
+  const duplicatePostureIds = duplicateValues(postures.map((posture) => posture.posture_id));
+  const duplicateSourceIds = duplicateValues(sources.map((source) => source.source_id));
+  const nodeIds = new Set(nodes.map((node) => node.node_id));
+  const missingEndpointEdgeIds = edges
+    .filter((edge) => !nodeIds.has(edge.from_node_id) || !nodeIds.has(edge.to_node_id))
+    .map((edge) => edge.edge_id)
+    .sort(compareByteOrder);
