+      'duplicate_ids_rejected',
+      duplicateNodeIds.length === 0
+        && duplicateEdgeIds.length === 0
+        && duplicatePostureIds.length === 0
+        && duplicateSourceIds.length === 0,
+      {
+        duplicate_node_ids: duplicateNodeIds,
+        duplicate_edge_ids: duplicateEdgeIds,
+        duplicate_posture_ids: duplicatePostureIds,
+        duplicate_source_ids: duplicateSourceIds,
+      },
+    ),
+    check('missing_edge_endpoints_rejected', missingEndpointEdgeIds.length === 0, {
+      missing_endpoint_edge_ids: missingEndpointEdgeIds,
+    }),
+    check('invalid_posture_enums_rejected', postureIssues.length === 0, {
+      invalid_posture_count: postureIssues.length,
+    }),
+    check('count_conservation_preserved', mismatches.length === 0, {
+      mismatches,
+    }),
+    check('stale_input_references_rejected', staleDiagnostics.length === 0 && inputDiagnostics.length === 0, {
+      stale_input_diagnostic_count: staleDiagnostics.length + inputDiagnostics.length,
+    }),
