+      graph?.full_source_coverage_claimed === false
+      && graph?.compile_summary?.full_source_coverage_claimed === false
+    ), {
+      graph_full_source_coverage_claimed: graph?.full_source_coverage_claimed ?? null,
+      summary_full_source_coverage_claimed: graph?.compile_summary?.full_source_coverage_claimed ?? null,
+    }),
