+  const failedChecks = checks.filter((item) => item.status !== 'pass');
+
+  return {
+    schema_version: 'kg_v1_runtime_spine_validator_result.v1',
+    generated_at: graph?.generated_at ?? DEFAULT_GENERATED_AT,
+    issue: '#1282',
+    parent_issue: '#1278',
+    producer_script: SCRIPT_NAME,
+    graph_path: DEFAULT_PATHS.graphOut,
+    summary: {
+      validation_status: failedChecks.length === 0 ? 'pass' : 'fail',
+      check_count: checks.length,
+      failing_check_count: failedChecks.length,
+      node_count: nodes.length,
+      edge_count: edges.length,
+      posture_count: postures.length,
+      source_count: sources.length,
+      full_source_coverage_claimed: graph?.compile_summary?.full_source_coverage_claimed === true,
+    },
+    checks,
+    input_diagnostics: [...inputDiagnostics, ...staleDiagnostics],
+    posture_diagnostics: postureIssues,
+  };
+}
+
+function buildReadback(graph, validatorResult) {
+  const sourceRows = graph.sources
+    .map((source) => `| \`${source.source_id}\` | ${source.source_family} | ${source.row_count ?? ''} | \`${source.path}\` |`)
+    .join('\n');
