+export function buildKgV1RuntimeSpine(options = {}) {
+  const root = options.root ?? repoRootFromScript();
+  const paths = { ...DEFAULT_PATHS, ...(options.paths ?? {}) };
+  const generatedAt = options.generatedAt ?? DEFAULT_GENERATED_AT;
+  const inputDiagnostics = [];
+  const manifest = safeReadJson(root, paths.sourceManifest, 'source_manifest', inputDiagnostics);
+  const contract = safeReadJson(root, paths.contract, 'contract', inputDiagnostics);
+  const graphSeed = asObject(options.graphSeed);
+  const nodes = normalizeNodes(graphSeed.nodes);
+  const edges = normalizeEdges(graphSeed.edges);
+  const postures = normalizePostures(graphSeed.postures);
+  const sources = sourceRowsFromManifest(manifest);
+  const graphMode = nodes.length || edges.length || postures.length ? FIXTURE_GRAPH_MODE : SKELETON_GRAPH_MODE;
