+      staleCheck.status = 'fail';
+      staleCheck.stale_input_diagnostic_count = validatorResult.input_diagnostics.length;
+    }
+    validatorResult.summary.failing_check_count = validatorResult.checks.filter((item) => item.status !== 'pass').length;
+    validatorResult.summary.validation_status = validatorResult.summary.failing_check_count === 0 ? 'pass' : 'fail';
+  }

